import "./zod-config";
import { StrictMode } from "react";
import ReactDOM from "react-dom/client";
import { QueryClientProvider } from "@tanstack/react-query";
import { createRouter, RouterProvider } from "@tanstack/react-router";
import { DirectionProvider } from "./context/direction-provider";
import { FontProvider } from "./context/font-provider";
import { ThemeProvider } from "./context/theme-provider";
import { queryClient, unauthorized } from "./query-client";
// Generated by @tanstack/router-plugin from src/routes.
import { routeTree } from "./routeTree.gen";

const router = createRouter({
    routeTree,
    context: { queryClient },
    defaultPreload: "intent",
    defaultPreloadStaleTime: 0,
    scrollRestoration: true,
});

// A query that comes back 401 means the session ended elsewhere: clear cached
// account data and send the user to sign in, then back to where they were.
unauthorized.handler = () => {
    const { pathname, href } = router.state.location;
    if (
        ["/sign-in", "/sign-up", "/forgot-password", "/recover"].includes(
            pathname,
        )
    )
        return;
    queryClient.clear();
    void router.navigate({
        to: "/sign-in",
        search: { redirect: href },
        replace: true,
    });
};

declare module "@tanstack/react-router" {
    interface Register {
        router: typeof router;
    }
}

const rootElement = document.getElementById("root");
if (!rootElement) throw new Error("Missing #root element.");

ReactDOM.createRoot(rootElement).render(
    <StrictMode>
        <QueryClientProvider client={queryClient}>
            <ThemeProvider>
                <FontProvider>
                    <DirectionProvider>
                        <RouterProvider router={router} />
                    </DirectionProvider>
                </FontProvider>
            </ThemeProvider>
        </QueryClientProvider>
    </StrictMode>,
);
